PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?director ?birthDate
WHERE {
  VALUES ?film { dbr:Let's_Live_Tonight dbr:Nice_Guy_Johnny }

  # director (prefer dbp:director, fallback to dbo:director)
  { ?film dbp:director ?director } UNION { ?film dbo:director ?director }

  # director's birth date (prefer dbp:birthDate, fallback to dbo:birthDate)
  OPTIONAL { ?director dbp:birthDate ?dbpBirth . }
  OPTIONAL { ?director dbo:birthDate ?dboBirth . }
  BIND (COALESCE(?dbpBirth, ?dboBirth) AS ?birthDate)
}
LIMIT 100
